// PreToolUse (Edit|Write): block hand edits of generated files.
import { readFileSync } from 'node:fs';
const input = JSON.parse(readFileSync(0, 'utf8')).tool_input ?? {};
const files = [input.file_path, input.path];
if (typeof input.patch === 'string') {
  for (const match of input.patch.matchAll(/^\*\*\* (?:(?:Add|Update|Delete) File|Move to): (.+)\r?$/gm)) files.push(match[1]);
}
const rules = [
  [/\/styles\/(brand|theme)\.css$/, 'Generated from tokens/: edit the JSON in tokens/ and run `pnpm tokens`.'],
  [/\/messages\/en\.d\.json\.ts$/, 'Generated by pnpm dev/build from messages/en.json: edit en.json instead.'],
];
for (const file of files) {
  if (typeof file !== 'string') continue;
  const f = `/${file.replaceAll('\\', '/')}`;
  for (const [re, why] of rules) {
    if (re.test(f)) {
      process.stdout.write(JSON.stringify({
        permissionDecision: 'deny',
        permissionDecisionReason: why,
        hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: why },
      }));
      process.exit(0);
    }
  }
}
